import sys

def solve(n, k, distances):
    graph = defaultdict(list)

    for i in range(1, n):
        start, end = distances[i-1], distances[i]
        if start < end:
            graph[start].append(end)
        elif end < start:
            graph[end].append(start)

    min_cost, path = sys.maxsize, deque([1])

    while path:
        last_city = path.popleft()
        cost = 0

        for neighbor in reversed(graph[last_city]):
            if cost + distances[neighbor] <= k:
                cost += distances[neighbor]
            else:
                cost = k
                path.appendleft(neighbor)

            if min_cost > cost:
                min_cost = cost
                deq = deque([last_city] + [neighbor for neighbor in graph[last_city] if neighbor not in deq])

