import sys

# Input function to read the list of cities
def read_input():
    n, q = map(int, input().split())
    cities = list(map(int, input().split()))
    queries = []
    for _ in range(q):
        l, r, d = map(int, input().split())
        queries.append((l-1, r-1, d))
    return cities, queries

# Output function to display 'Yes' or 'No'
def display_output(answers):
    for answer in answers:
        print(answer)

# Function to determine if a range of cities can be connected with roads of a given length
def can_connect(cities, queries):
    MOD = 10**9 + 7
    prefix = [0] * len(cities)

    # Calculate prefix sums
    for i in range(1, len(cities)):
        prefix[i] = prefix[i-1] + cities[i]

    # Check if any city sequence can connect within the query range
    for l, r, d in queries:
        # Avoid wrapping around for circular arrangement
        if r - l + 1 < d:
            return "No"
        # Check if any prefix sum can connect up to d with its remainder
        for k in range(r - l + 1, len(cities)):
            if prefix[k + 1] - prefix[k - r + l] <= d:
                return "Yes"

    return "No"

# Main function to process input and output results
def main():
    cities, queries = read_input()
    results = can_connect(cities, queries)
    display_output(results)

if __name__ == "__main__":
