            if not i & l:
                left_child = len(level_1) + 1
                right_child = left_child + 1
                new_level.append(right_child)
                level_1.append(left_child)
            else:
                right_child = len(level_1) + 1
                new_level.append(right_child)
                level_1.append(right_child + 1)
        level_1.append(-1)  # End marker

    operations = []
    for _ in range(m):
        operation = list(map(int, input().strip().split()))
        operations.append(operation)

    return n, level_1, operations

# Function to perform union operations
def union_sets(tree, node, parent=None):
    if parent is None:
        parent = [{} for _ in range(len(tree))]

    for child in range(len(tree)):
        if node[0] == child:
            continue
        if node[1] in tree[child]:
            tree[parent[child]][node[1]].add(node[2])
            del tree[child][node[1]]
        if child not in tree[node[0]]:
            tree[node[0]][child] = {}
        if node[1] in tree[parent[child]]:
            tree[parent[child]][node[1]].add(node[2])
            del tree[child][node[1]]
        tree[node[0]][child][node[1]] = {node[2]}
        tree[parent[child]][node[1]][node[2]] = {node[2]}

def find_size(tree, node):
    if node[0] == -1:
        return 0

    size = 0
    for child in tree[node[0]]:
        if node[1] in tree[child]:
            size += find_size(tree, tree[child][node[1]])
    return size + 1

def process_operation(n, operations):
    tree = [{} for _ in range(n)]
    for operation in operations:
        if operation[0] == 1:
            x, t, l, r, value = operation[1], operation[2], operation[3], operation[4], operation[5]
            for level in range(t, t + 1):
                add_value = x
                if x not in tree[level]:
                    tree[level][x] = defaultdict(int)
                for old_level in range(level - 1, -1, -1):
                    if tree[level][add_value]:
                        add_value = tree[level][add_value][value]
                tree[level][x][value] = set([x])
                tree[t][--l][x][value].add(add_value)

        elif operation[0] == 2:
            t, v = operation[1], operation[2]
            i = 0
            while v != -1:
                if v in tree[t]:
                    if v != tree[t][-1][v]:
                        union_sets(tree, tree[t][v])
                    size = find_size(tree, tree[t][v])
                    tree[t][-1][v], tree[t][{}][v] = size, size
                    v = tree[t][-1][v]
                else:
                    if tree[t][-1][v]:
                        union_sets(tree, tree[t][-1][v])
                    tree[t][-1][v], tree[t][{}][v] = find_size(tree, tree[t][-1][v]), find_size(tree, tree[t][-1][v])
                    tree[t][{}][v], tree[t][v] = tree[t][-1][v], tree[t][{}][v]
                    v, tree[t][-1][{}, v] = v, tree[t][-1][{}][v]
                i = 1

    return tree

