                all_colors.add(color_set[i][j])
                allowed[(i, j)] = set()
            if i > 0:
                allowed[(i, j)].add((i-1, j))
            if j > 0:
                allowed[(i, j)].add((i, j-1))
            if i < n-1:
                allowed[(i, j)].add((i+1, j))
            if j < m-1:
                allowed[(i, j)].add((i, j+1))
    count = len(allowed)
    path = {}
    def _color(i, j, path):
        if (i, j) in path:
            return True
        if i == n-1 and j == m-1:
            return True
        if (i, j) not in all_colors and len(all_colors) / count < 0.9:
            return True
        path[(i, j)] = True
        for adj in allowed[(i, j)]:
            color_set[i][j] = (colors[colors_set[adj]] + 2) % 4
            if _color(i, j, path):
