from collections import defaultdict, Counter

def count_occurrences(s, num_qubits, qubits):
    powers = defaultdict(set)
    for digit, count in qubits.items():
        for num in range(num_qubits):
            power = 1 << num
            for multiple in range(1, 1 + int(sqrt(count / pow(2, num))) + 1):
                power += (count // pow(multiple, num)) * multiple
            powers[digit].add(power % qubits[digit])

    count = Counter(s)
    prefix_sum = [0]
    for k in count:
        count[k] += prefix_sum[-1]
        prefix_sum.append(count[k])

    results = defaultdict(int)
    for digit in powers.keys():
        bit_mask = 1 << ((int)(ceil(sqrt(count[digit])) - 1))
        for block in bit_mask:
            for start in range(0, 2 << bit_mask.bit_length() - 1, bit_mask):
                k_text = format(start, f'0{bit_mask.bit_length()}b')
                exp = Counter([int(i) for i in k_text])
                sum_of_exponents = (powers[digit] - counters.subtract(counters, exp))
                results[len(sum_of_exponents)] += 2 ** len(k_text) % (10 ** 9 + 7)

    return (2 ** int(s, 2)) * results[0] % (10 ** 9 + 7)
