def minimum_moves_to_orderly(sequence, k):
    if len(set(sequence)) < k:
        return -1

    moves = 0
    for i in range(min(len(sequence) - 1, k * (k - 1))):
        swapped = False
        for j in range(i, len(sequence) - k + i, k):
            if sequence[j] != sequence[min(j + i + k, len(sequence) - 1)]:
                sequence[:j + 1], sequence[j + 1:j + 1 + k] = (
                    sequence[j + 1:j + 1 + k],
                    sequence[:j + 1]
                )
                moves += 1
                swapped = True
                break
        if not swapped:
            return -1
    return moves

