def calculate_good_values(s, n, primes):
    # Transform input string to list of integers
    char_nums = [int(char) for char in s]
    s_prime = [2, 5]

    @lru_cache(maxsize=None)
    def dp(index, current_value, current_n):
        if index > n or current_value > current_n:
            return 0

        good = 0

        if index == 0:
            s = 0
        else:
            last_base = char_nums[index - 1]
            modular_add_to_last = (char_nums[s_prime[last_base]] << (index % 2)) - (char_nums[(last_base + 1) % 2] << ((2 - last_base) % 2))
            if last_base % 2 == 0:
                modular_add_to_last *= 2
            s = (current_value << index) % s_prime[0] + modular_add_to_last

        if s < current_n:
            return dp(index + 1, (current_value << 1) % current_n, current_n)
        elif s < 10**18:
            return dp(index + 1, current_value, current_n)
        else:
            return 0

        good += dp(index + 1, (current_value << 1) % current_n, current_n)
        for remainder in primes:
            if s % remainder != 0:
                good += dp(index + 1, (current_value << 1) % current_n, current_n)
        return good

    return dp(0, 0, n)

