from fractions import Fraction

def expected_collision_time(n, pipes):
    durations = []
    for i in range(1, n + 1):
        x_i, v_i, p_i = pipes[i-1]
        left_collision_times = []
        for j in range(1, i):
            x_j, v_j, p_j = pipes[j-1]
            crossing_time = (x_i - x_j) / (v_i + v_j * (p_i - p_j) / (v_i - v_j))
            right_collision_times = []
            for k in range(j + 1, i + 1):
                x_k, v_k, p_k = pipes[k-1]
                if p_k > (v_j * (1 - p_j) / (v_i - v_j)) * crossing_time:
                    right_collision_times.append((x_i - x_k) / (v_i - v_j))
                else:
                    right_collision_times.append((x_k - x_i) / (v_k - v_i))
            if right_collision_times:
                left_collision_times.append(min(right_collision_times))
            else:
                left_collision_times.append(crossing_time)
        efficiencies = []
        for j in range(0, len(right_collision_times) + 1):
            value = Fraction(1.0 * sum(left_collision_times[j:] + right_collision_times[j:]), len(right_collision_times) + len(left_collision_times) - j)
            efficiencies.append(value)
        if efficiencies:
            max_efficiency = max(efficiencies)
        else:
            max_efficiency = Fraction(1.0)
        durations.append(max_efficiency)
    return durations

