import bisect

class Tree:
    def __init__(self, n):
        self.n = n
        self.cnt = [0] * (n + 1)
        self.left = [self.right = [-1] * (n + 1) for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            self.cnt[i] = 0
            for j in range(self.cnt[i] + 1):
                if j % 2 == 1:
                    self.left[i][j] = self.cnt[i + 1] + 1
                    self.right[i][j] = self.cnt[i + 1] + 2
                    self.cnt[i + 1] += 2
                else:
                    self.right[i][j] = self.cnt[i + 1] + 1
                    self.cnt[i + 1] += 1

    def add(self, t, l, r, x):
        for i in range(l, min(r + 1, self.n)):
            if i % 2 == 0:
                self.left[t][i] -= 1
            else:
                self.right[t][i] -= 1
            self.cnt[t] += 1
            if self.cnt[t] > 1:
                self.cnt[t] -= 1
        if not x and (l & 1) == 0: 
            self.left[t][0] -= 1
            self.right[t][1] -= 1
        if x: 
            if l > 1: 
                self.left[t][l - 2] += 1
            if l < self.n: 
                self.right[t][l] += 1
        for i in range(r, l - 1, -1):
            if i % 2 == 0:
                self.right[t][i] -= 1
            else:
                self.left[t][i] -= 1
            self.cnt[t] -= 1
            if self.cnt[t] == 0:
                self.cnt[t] = self.left[t][0] = self.right[t][1] = -1

    def query(self, t, v):
        result = 0
        for i in range(v, min(v + 1, self.n)):
            if i % 2 == 0:
                bisect.insort_left(self.left[t], i - 1)
                bisect.insort(self.right[t], i)
                result += len(self.left[t])
            else:
                bisect.insort_left(self.left[t], i - 1)
                bisect.insort(self.right[t], i)
                result += len(self.right[t])
        return result


