        for i in range(len(s) - 1):
            p = s[i] / s[i+1]
            t = get_res(i, p, len(s), p-t, 0)
            b = pow(p, MOD-2, MOD)
            s[i+1] = ((s[i+1] - min(s, s[i+2]) - 2*t - s[i+2]) * b) % MOD
            st[i+1] = (max(s, s[i+2]) + 2*s[i+1] + t) * b % MOD
        if s[-1] - t < t or s[-1] == min(s) and any((abs(i-s[-1]) - min(s) - s[-1]) > t for i in range(len(s))):
            return

if __name__ == '__main__':
