def find_min_moves_to_make_40(arr):
    if len(arr) < 4:
        return -1  # Impossible to make an orderly subsequence of length 4

    dp = [0] * 4
    result = 0

    for i in range(3, len(arr) - 2):
        current = arr[i + 1]  # Store first consecutive value
        dp[current - arr[i - 1]] = 0  # Reset for current value

        for j in range(i, len(arr) - 1):
            previous = arr[j - 1]  # Store second consecutive value
            if previous == previous - 1 == current - 1 == current + 1:
                result += 1
            else:
                ongoing_moves = 1
                duplicate_count = 1
                for k in range(j, len(arr) - 1):
                    if arr[k] == arr[k + 1]:
                        duplicate_count += 1
                    else:
                        dp[arr[k] - arr[k - 2]] = ongoing_moves + dp[arr[k] - arr[k - 2]]
                        ongoing_moves = 0
                    if duplicate_count == 3:
                        return -1
                elif -2 in dp or 3 in dp or 4 in dp:
                    return -1
            result += ongoing_moves

    return result

T = int(input())
for _ in range(T):
    N, K = map(int, input().split())
    A = list(map(int, input().split()))
    print(find_min_moves_to_make_40(A))
