import math
from itertools import chain, count

def factorial(n):
    """Compute n!"""
    return math.factorial(n)

def inv_mod(n, mod):
    """Compute inverse of n modulo mod"""
    return pow(n, mod - 2, mod)

def combinations(r, n, mod):
    """Compute nCr (factorial division) modulo mod"""
    return factorial(n) * inv_mod(factorial(r), mod) * inv_mod(factorial(n - r), mod) % mod

def count_good_sequences(n, mod=998244353):
    """Count f_p(k) for all 1 ≤ k ≤ n"""
    count = [0] * (n + 1)
    dp = [0] * (n + 1)

    dp[0], dp[1] = 1, 1

    for i in range(1, n + 1):
        dp[i] = combinations(i, 1, mod) + dp[i - 1] * combinations(i - 1, 0, mod) % mod

        # For each k in previous windows, calculate f_p(k)
        for k in range(i, 1, -1):
            if k * (k - 1 <= i):
                count[k] = (count[k] + dp[i - k]) % mod

    return sum(count[i] for i in range(1, n + 1)) % mod

def solution(n):
    return [count_good_sequences(n) for _ in range(n)]

# Example usage
n = 3
print(solution(n))
